-- Loads the curated dimensions and facts from the staging tables.
-- Run by src/build_curated.py, which sends one statement at a time (each ends with a semicolon).
-- dim_date is generated by src/calendar_dim.py before these statements run.
-- Each "-- step:" line names the statement that follows it, for the log.

-- step: dim_customer (unknown member)
INSERT INTO curated.dim_customer (customer_key, customer_id, customer_name, customer_type, state, city, sales_territory, is_unknown)
VALUES (-1, 'UNKNOWN', 'Unknown customer', 'Unknown', 'Unknown', 'Unknown', 'Unknown', 1);

-- step: dim_customer
INSERT INTO curated.dim_customer (customer_key, customer_id, customer_name, customer_type, state, city, sales_territory, is_unknown)
SELECT ROW_NUMBER() OVER (ORDER BY customer_id), customer_id, customer_name, customer_type, state, city, sales_territory, 0
FROM staging.customer_master;

-- step: dim_product
INSERT INTO curated.dim_product (product_key, product_id, product_name, category, brand, list_price_ngn, unit_cost_ngn, reorder_level_units, active_flag)
SELECT ROW_NUMBER() OVER (ORDER BY product_id), product_id, product_name, category, brand, list_price_ngn, unit_cost_ngn, reorder_level_units, active_flag
FROM staging.product_master;

-- step: dim_warehouse
INSERT INTO curated.dim_warehouse (warehouse_key, warehouse_id, warehouse_name, warehouse_state)
SELECT ROW_NUMBER() OVER (ORDER BY warehouse_id), warehouse_id, warehouse_name, warehouse_state
FROM (SELECT DISTINCT warehouse_id, warehouse_name, warehouse_state FROM staging.inventory_snapshot) AS w;

-- step: dim_sales_channel
INSERT INTO curated.dim_sales_channel (channel_key, sales_channel)
SELECT ROW_NUMBER() OVER (ORDER BY sales_channel), sales_channel
FROM (SELECT DISTINCT sales_channel FROM staging.sales_transactions) AS c;

-- step: dim_order_status
INSERT INTO curated.dim_order_status (status_key, order_status, status_group, counts_as_revenue)
SELECT ROW_NUMBER() OVER (ORDER BY order_status),
       order_status,
       CASE order_status
            WHEN 'Delivered' THEN 'Completed'
            WHEN 'Returned'  THEN 'Returned'
            WHEN 'Pending'   THEN 'Open'
            WHEN 'Cancelled' THEN 'Cancelled'
       END,
       CASE WHEN order_status = 'Delivered' THEN 1 ELSE 0 END
FROM (SELECT DISTINCT order_status FROM staging.sales_transactions) AS s;

-- step: fact_sales
INSERT INTO curated.fact_sales (sales_key, transaction_id, date_key, customer_key, product_key, channel_key, status_key,
                                transaction_datetime, quantity, unit_price_ngn, discount_pct, gross_sales_ngn,
                                discount_amount_ngn, net_sales_ngn, is_missing_customer, is_duplicate_transaction_id)
SELECT s.sales_key, s.transaction_id, d.date_key, c.customer_key, p.product_key, ch.channel_key, st.status_key,
       s.transaction_datetime, s.quantity, s.unit_price_ngn, s.discount_pct, s.gross_sales_ngn,
       s.discount_amount_ngn, s.net_sales_ngn, s.is_missing_customer, s.is_duplicate_transaction_id
FROM staging.sales_transactions AS s
JOIN curated.dim_date          AS d  ON d.full_date = CAST(s.transaction_datetime AS DATE)
JOIN curated.dim_customer      AS c  ON c.customer_id = s.customer_id
JOIN curated.dim_product       AS p  ON p.product_id = s.product_id
JOIN curated.dim_sales_channel AS ch ON ch.sales_channel = s.sales_channel
JOIN curated.dim_order_status  AS st ON st.order_status = s.order_status;

-- step: fact_inventory_snapshot
INSERT INTO curated.fact_inventory_snapshot (snapshot_key, inventory_record_id, date_key, product_key, warehouse_key,
                                             on_hand_units, reserved_units, available_units, reorder_level_units, is_below_reorder)
SELECT ROW_NUMBER() OVER (ORDER BY s.inventory_record_id), s.inventory_record_id, d.date_key, p.product_key, w.warehouse_key,
       s.on_hand_units, s.reserved_units, s.available_units, s.reorder_level_units,
       CASE WHEN s.available_units < s.reorder_level_units THEN 1 ELSE 0 END
FROM staging.inventory_snapshot AS s
JOIN curated.dim_date      AS d ON d.full_date = s.snapshot_date
JOIN curated.dim_product   AS p ON p.product_id = s.product_id
JOIN curated.dim_warehouse AS w ON w.warehouse_id = s.warehouse_id;

-- step: fact_inventory_movement
INSERT INTO curated.fact_inventory_movement (movement_key, movement_id, date_key, product_key, warehouse_key, movement_datetime,
                                             movement_type, reference_type, reference_id, approval_status, quantity_change,
                                             is_duplicate_movement_id, is_zero_quantity)
SELECT m.movement_key, m.movement_id, d.date_key, p.product_key, w.warehouse_key, m.movement_datetime,
       m.movement_type, m.reference_type, m.reference_id, m.approval_status, m.quantity_change,
       m.is_duplicate_movement_id, m.is_zero_quantity
FROM staging.inventory_movements AS m
JOIN curated.dim_date      AS d ON d.full_date = CAST(m.movement_datetime AS DATE)
JOIN curated.dim_product   AS p ON p.product_id = m.product_id
JOIN curated.dim_warehouse AS w ON w.warehouse_id = m.warehouse_id;
